//! Observer-chosen viewing positions test physical access, not learned search.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-teacher-task.rs"] mod task;
#[path = "../runs/quality-research/navigation-viewpoint-teacher.rs"] mod teacher;
use task::{Task,Route};
use flight_control::FlightPilot;
#[test]
fn audit_observed_teacher(){
 let pilot=FlightPilot::bundled().unwrap();let mut rows=Vec::new();
 for route in [Route::House,Route::Pipe]{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route);let mut trace=Vec::new();let mut teacher=teacher::Teacher::default();
  while !task.ended&&task.steps<3000{
   let action=teacher.action(&task);task.advance(&action,&pilot);trace.push(task.trace());
  }
  let mut row=task.result();row["seed"]=seed.into();row["trace"]=trace.into();rows.push(row);
 }}println!("TEACHER_AUDIT={}",serde_json::to_string(&rows).unwrap());
 assert!(rows.iter().all(|row|!row["ended"].as_bool().unwrap()&&row["trace"].as_array().unwrap().iter().rev().take(100).all(|s|s["visible"].as_bool().unwrap())));
}

//! Measure unseen house and pipe challenges without changing the selected navigator.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-hide-task.rs"] mod task;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoConfig,RecurrentPpoPolicy};
#[test]
fn audit_hidden_target(){
 let pilot=FlightPilot::bundled().unwrap();let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],..Default::default()};
 let candidate=std::env::var("NAVIGATOR_CANDIDATE").unwrap();
 let policy=RecurrentPpoPolicy::load(&candidate,32,32,1,&[-1.0;4],&[1.0;4],&config).unwrap();let memory=policy.initial_memory();let mut rows=Vec::new();
 for route in [Route::House,Route::Pipe]{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route);let mut trace=Vec::new();
  while !task.ended&&task.steps<3000{let action=policy.mean_action(&task.features(),&memory).unwrap().action;task.advance(&action,&pilot);trace.push(task.trace());}
  let mut row=task.result();row["seed"]=seed.into();row["trace"]=trace.into();rows.push(row);
 }}
 println!("HIDE_AUDIT={}",serde_json::to_string(&rows).unwrap());
 let arena=arena::Arena::default();let geometry:Vec<_>=arena.blocks().iter().map(|block|serde_json::json!({"centre":block.centre.to_array(),"half":block.half.to_array(),"rotation":block.rotation.to_array(),"surface":format!("{:?}",block.surface)})).collect();println!("ARENA_GEOMETRY={}",serde_json::to_string(&geometry).unwrap());
}

//! Research only: train carried navigator memory while freezing the motor pilot.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-hide-task.rs"] mod task;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoAgent,RecurrentPpoPolicy,RecurrentPpoConfig,RecurrentPpoSequence,RecurrentSampler,RecurrentMemory,SeedConfig};
struct Transition{input:Vec<f32>,raw:Vec<f32>,log:f32,value:f32,next:f32,reward:f32,terminal:bool,boundary:bool,memory:RecurrentMemory,advantage:f32}
struct Lane{task:Task,sampler:RecurrentSampler,episode:u64,memory:RecurrentMemory}
fn route(index:usize)->Route{match index%5{0=>Route::Stationary,1=>Route::Lateral,2=>Route::Approach,3=>Route::House,_=>Route::Pipe}}
fn evaluate(policy:&RecurrentPpoPolicy,pilot:&FlightPilot)->serde_json::Value{
 let mut rows=Vec::new();for course in 0..5{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route(course));let mut memory=policy.initial_memory();let mut hidden_visible=0;let mut hidden_samples=0;
  while !task.ended&&task.steps<3000{let action=policy.mean_action(&task.features(),&memory).unwrap();memory=action.next_memory;task.advance(&action.action,pilot);let trace=task.trace();if trace["hold"].as_u64().unwrap()>0{hidden_samples+=1;if trace["visible"].as_bool().unwrap(){hidden_visible+=1;}}}
  let mut result=task.result();result["seed"]=seed.into();result["hidden_visible_samples"]=hidden_visible.into();result["hidden_samples"]=hidden_samples.into();rows.push(result);
 }}serde_json::json!(rows)
}
#[test]
fn train_memory_navigator(){
 let pilot=FlightPilot::bundled().unwrap();let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],actor_learning_rate:0.0001,critic_learning_rate:0.001,minibatch_sequences:32,entropy_coefficient:0.001,initial_log_std:-2.0,log_std_min:-3.0,log_std_max:-2.0,..Default::default()};
 let seeds=SeedConfig::from_root(29);let mut agent=RecurrentPpoAgent::load_actor_with_fresh_critic("docs/progress/drone-navigation-cover.mpk",32,32,1,&[-1.0;4],&[1.0;4],config,seeds).unwrap();
 let seed=|lane:usize,episode:u64|(seeds.environment_episode(lane,episode)&(u64::MAX>>1))|(1<<10);
 let mut lanes:Vec<_>=(0..8).map(|index|Lane{task:Task::new(seed(index,0),route(index)),sampler:RecurrentSampler::new(seeds.action.wrapping_add(index as u64)),episode:0,memory:agent.policy().initial_memory()}).collect();
 std::fs::create_dir_all("runs/quality-research/navigation-memory-ppo").unwrap();
 let initial=evaluate(&agent.policy(),&pilot);println!("INITIAL={initial}");std::fs::write("runs/quality-research/navigation-memory-ppo/0.json",initial.to_string()).unwrap();
 for update in 1..=300{
  let policy=agent.policy();let mut sequences=Vec::new();
  for (index,lane) in lanes.iter_mut().enumerate(){
   let mut transitions=Vec::new();
   for _ in 0..64{
    let input=lane.task.features();let memory=lane.memory.clone();let action=policy.sample_action(&input,&memory,&mut lane.sampler).unwrap();lane.memory=action.next_memory;let value=policy.value(&input,0).unwrap();let reward=lane.task.advance(&action.action,&pilot);let next=policy.value(&lane.task.features(),0).unwrap();let terminal=lane.task.ended;let boundary=terminal||lane.task.steps>=3000;
    transitions.push(Transition{input,raw:action.pre_tanh_action,log:action.log_probability,value,next,reward,terminal,boundary,memory,advantage:0.0});
    if boundary{lane.episode+=1;lane.task=Task::new(seed(index,lane.episode),route(index+lane.episode as usize));lane.memory=policy.initial_memory();}
   }
   let mut advantage=0.0;
   for t in transitions.iter_mut().rev(){
    let bootstrap=if t.terminal{0.0}else{1.0};let trace=if t.boundary{0.0}else{1.0};let delta=t.reward+0.99*bootstrap*t.next-t.value;advantage=delta+0.99*0.95*trace*advantage;t.advantage=advantage;
   }
   // Split only at episode boundaries or sixteen decisions; preserve temporal order.
   let mut offset=0;while offset<transitions.len(){
    let remaining=&transitions[offset..];let length=remaining.iter().take(16).position(|t|t.boundary).map_or(remaining.len().min(16),|index|index+1);let segment=&remaining[..length];
    sequences.push(RecurrentPpoSequence{observations:segment.iter().map(|t|t.input.clone()).collect(),global_states:segment.iter().map(|t|t.input.clone()).collect(),pre_tanh_actions:segment.iter().map(|t|t.raw.clone()).collect(),old_log_probabilities:segment.iter().map(|t|t.log).collect(),advantages:segment.iter().map(|t|t.advantage).collect(),returns:segment.iter().map(|t|t.value+t.advantage).collect(),value_index:0,initial_memory:segment[0].memory.clone()});offset+=length;
   }
  }
  if update==1{for _ in 0..10{agent.update_critic(&sequences).unwrap();}}
  let metrics=agent.update(&sequences).unwrap();
  if update==1||update%20==0{let policy=agent.policy();let scores=evaluate(&policy,&pilot);println!("UPDATE={update} METRICS={metrics:?} SCORES={scores}");std::fs::write(format!("runs/quality-research/navigation-memory-ppo/{update}.json"),scores.to_string()).unwrap();std::fs::write(format!("runs/quality-research/navigation-memory-ppo/{update}.mpk"),policy.to_bytes().unwrap()).unwrap();}
 }
}

//! Experimental imitation training; this does not install a gameplay controller.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-teacher-task.rs"] mod task;
#[path = "../runs/quality-research/navigation-viewpoint-teacher.rs"] mod teacher;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoAgent,RecurrentPpoPolicy,RecurrentPpoConfig,RecurrentBehaviorSample,SeedConfig,SplitMix64};
fn evaluate(policy:Option<&RecurrentPpoPolicy>,pilot:&FlightPilot)->serde_json::Value{
 let mut rows=Vec::new();for route in [Route::House,Route::Pipe]{for seed in [0,1,2,42,u64::MAX]{
  let mut teacher=teacher::Teacher::default();let mut hidden_samples=0;let mut hidden_visible=0;let mut task=Task::new(seed,route);let memory=policy.map(RecurrentPpoPolicy::initial_memory);
  while !task.ended&&task.steps<3000{let expert=teacher.action(&task);let action=policy.map_or_else(||expert,|p|p.mean_action(&task.features(),memory.as_ref().unwrap()).unwrap().action);task.advance(&action,pilot);let trace=task.trace();if trace["hold"].as_u64().unwrap()>0{hidden_samples+=1;if trace["visible"].as_bool().unwrap(){hidden_visible+=1;}}}
  let mut result=task.result();result["seed"]=seed.into();result["hidden_samples"]=hidden_samples.into();result["hidden_visible_samples"]=hidden_visible.into();rows.push(result);
 }}serde_json::json!(rows)
}
#[test]
fn train_viewpoint_navigator(){
 let pilot=FlightPilot::bundled().unwrap();let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],actor_learning_rate:0.001,..Default::default()};
 let seeds=SeedConfig::from_root(37);let mut agent=RecurrentPpoAgent::load_actor_with_fresh_critic("runs/quality-research/navigation-viewpoint-imitation/280.mpk",32,32,1,&[-1.0;4],&[1.0;4],config,seeds).unwrap();let mut random=SplitMix64::new(0x4e41564947415445);
 let mut replay=Vec::new();
 println!("TEACHER={}",evaluate(None,&pilot));
 for episode in 0..20{let mut teacher=teacher::Teacher::default();let route=if episode%2==0{Route::House}else{Route::Pipe};let mut task=Task::new((seeds.environment_episode(0,episode)&(u64::MAX>>1))|(1<<10),route);
  while !task.ended&&task.steps<3000{let action=teacher.action(&task);if task.steps<750||task.steps%50==0{replay.push(RecurrentBehaviorSample{observation:task.features(),action:action.clone()});}task.advance(&action,&pilot);}
 }
 std::fs::create_dir_all("runs/quality-research/navigation-viewpoint-imitation-wide").unwrap();
 for update in 1..=300{
  let batch:Vec<_>=(0..512).map(|_|replay[(random.unit_f64()*replay.len() as f64) as usize].clone()).collect();let mut loss=0.0;for _ in 0..4{loss=agent.behavior_clone(&batch).unwrap();}
  if update%5==0{let policy=agent.policy();let memory=policy.initial_memory();let mut teacher=teacher::Teacher::default();let route=if (update/5)%2==0{Route::House}else{Route::Pipe};let mut task=Task::new((seeds.environment_episode(1,1000+update)&(u64::MAX>>1))|(1<<10),route);
   while !task.ended&&task.steps<3000{let input=task.features();replay.push(RecurrentBehaviorSample{observation:input.clone(),action:teacher.action(&task)});let action=policy.mean_action(&input,&memory).unwrap().action;task.advance(&action,&pilot);}
   if replay.len()>30000{replay.drain(..replay.len()-30000);}
  }
  if update==1||update%20==0{let policy=agent.policy();let scores=evaluate(Some(&policy),&pilot);println!("UPDATE={update} LOSS={loss} SCORES={scores}");std::fs::write(format!("runs/quality-research/navigation-viewpoint-imitation-wide/{update}.json"),scores.to_string()).unwrap();std::fs::write(format!("runs/quality-research/navigation-viewpoint-imitation-wide/{update}.mpk"),policy.to_bytes().unwrap()).unwrap();}
 }
}

//! Observer-chosen viewing positions test physical access, not learned search.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-viewpoint-task.rs"] mod task;
use bevy::math::Vec3;
use task::{Task,Route};
use flight_control::FlightPilot;
#[test]
fn calibrate_viewpoints(){
 let pilot=FlightPilot::bundled().unwrap();let mut rows=Vec::new();
 for route in [Route::House,Route::Pipe]{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route);let mut trace=Vec::new();let mut stage=0;
  let goals=match route{Route::House=>[Vec3::new(-1.0,2.0,1.5),Vec3::new(-5.0,2.0,1.5),Vec3::new(-5.0,2.0,1.5)],_=>[Vec3::new(0.0,2.0,8.0),Vec3::new(5.0,2.0,8.0),Vec3::new(5.0,1.6,6.0)]};
  while !task.ended&&task.steps<3000{
   if stage+1<goals.len()&&task.observation().position().distance(goals[stage])<0.25{stage+=1;}
   let action=task.goal_action(goals[stage],Vec3::NEG_Z);task.advance(&action,&pilot);trace.push(task.trace());
  }
  let mut row=task.result();row["seed"]=seed.into();row["trace"]=trace.into();rows.push(row);
 }}println!("VIEWPOINT_AUDIT={}",serde_json::to_string(&rows).unwrap());
 assert!(rows.iter().all(|row|!row["ended"].as_bool().unwrap()&&row["trace"].as_array().unwrap().iter().rev().take(100).all(|s|s["visible"].as_bool().unwrap())));
}

//! Experimental ten-hertz navigation task over the unchanged fifty-hertz flight pilot.
use super::{arena::{Arena,Movement,layout::Surface},sight::{Sight,Contact},flight_control::{FlightGoal,FlightPilot}};
use bevy::math::{Dir2,Dir3,Vec2,Vec3};
use bevy_gym::{Env,robots::{DroneHover,DroneObstacle,DroneObservation}};
use std::time::Duration;

#[derive(Clone,Copy,Debug)]
pub enum Route {Stationary,Lateral,Approach,House,Pipe}
pub struct Task {
 arena:Arena,drone:DroneHover,sight:Sight,previous_visible:Option<Vec3>,velocity:Vec3,
 route:Route,right:bool,back:bool,stage:usize,hold:u32,pub steps:u32,pub visible:u32,pub first_seen:Option<u32>,pub ended:bool,pub score:f32,
}
impl Task {
 pub fn new(seed:u64,route:Route)->Self {
  let arena=Arena::default();
  let obstacles=arena.blocks().iter().filter(|b|b.surface!=Surface::Floor).map(|b|DroneObstacle::try_from((b.centre,b.half,b.rotation)).unwrap());
  let mut drone=DroneHover::with_obstacles(obstacles);drone.reset(Some(seed));
  Self{arena,drone,sight:Sight::default(),previous_visible:None,velocity:Vec3::ZERO,route,right:true,back:false,stage:0,hold:0,steps:0,visible:0,first_seen:None,ended:false,score:0.0}
 }
 pub fn observation(&self)->DroneObservation{self.drone.observation()}
 fn rays(&self)->[(Vec3,f32);8]{
  let current=self.observation();let forward=current.orientation()*Vec3::NEG_Z;
  let forward=Vec3::new(forward.x,0.0,forward.z).normalize_or_zero();let right=Vec3::new(-forward.z,0.0,forward.x);
  std::array::from_fn(|index|{
   let angle=index as f32*std::f32::consts::TAU/8.0;let direction=right*angle.cos()+forward*angle.sin();
   let distance=[-0.4_f32,0.0,0.4].into_iter().map(|height|{let from=current.position()+Vec3::Y*height;self.arena.obstruction(from,from+direction*3.0).unwrap_or(3.0)}).fold(3.0_f32,f32::min);
   (direction,distance)
  })
 }
 pub fn features(&self)->Vec<f32>{
  let obs=self.observation();let inverse=obs.orientation().inverse();let body_velocity=inverse*obs.linear_velocity()/4.0;
  let gravity=inverse*Vec3::Y;let angular=obs.angular_velocity()/4.0;let forward=obs.orientation()*Vec3::NEG_Z;
  let mut input=vec![obs.position().y/3.0];input.extend(body_velocity.to_array());input.extend(gravity.to_array());input.extend(angular.to_array());input.extend([forward.x,forward.z,obs.position().x/10.0,obs.position().z/10.0]);
  let (point,flags,age)=match self.sight.contact(){Contact::Unknown=>(obs.position(),[1.0,0.0,0.0],0.0),Contact::Visible(p)=>(p,[0.0,1.0,0.0],0.0),Contact::Remembered{point,age}=>(point,[0.0,0.0,1.0],age.as_secs_f32()/3.0)};
  input.extend((inverse*(point-obs.position())/10.0).to_array());input.extend(flags);input.push(age);input.extend((inverse*self.velocity/4.0).to_array());input.extend(self.rays().map(|(_,range)|range/3.0));assert_eq!(input.len(),32);input
 }
 pub fn teacher(&self)->Vec<f32>{
  let obs=self.observation();let current=obs.position();let forward=obs.orientation()*Vec3::NEG_Z;
  let (position,yaw)=match self.sight.contact(){
   Contact::Unknown=>(Vec3::new(current.x,2.5,current.z),0.5),
   contact=>{
    let (point,age)=match contact{Contact::Visible(point)=>(point,0.0),Contact::Remembered{point,age}=>(point,age.as_secs_f32()),Contact::Unknown=>unreachable!()};
    let point=point+self.velocity*(age+0.5);let direction=Vec3::new(point.x-current.x,0.0,point.z-current.z).normalize_or_zero();
    (Vec3::new(point.x,2.5,point.z)-direction*5.0,forward.cross(direction).y.atan2(forward.dot(direction)))
   }
  };
  let mut displacement=(position-current).clamp_length_max(3.0);
  for (direction,distance) in self.rays(){if distance<2.0{displacement-=direction*(2.0-distance)*2.0;}}
  let body=obs.orientation().inverse()*displacement.clamp_length_max(3.0)/3.0;
  vec![body.x,body.y,body.z,yaw/std::f32::consts::PI]
 }
 pub fn advance(&mut self,action:&[f32],pilot:&FlightPilot)->f32{
  assert!(!self.ended&&self.steps<3000);assert_eq!(action.len(),4);assert!(action.iter().all(|v|v.is_finite()&&(-1.0..=1.0).contains(v)));
  let obs=self.observation();let position=(obs.position()+obs.orientation()*Vec3::new(action[0],action[1],action[2])*3.0).clamp(Vec3::new(-9.5,1.0,-9.5),Vec3::new(9.5,4.0,9.5));
  let forward=bevy::math::Quat::from_rotation_y(action[3]*std::f32::consts::PI)*(obs.orientation()*Vec3::NEG_Z);let heading=Dir2::new(Vec2::new(forward.x,forward.z)).unwrap_or(Dir2::X);
  let goal=FlightGoal::try_from((position,heading)).unwrap();let mut reward=0.0;
  for _ in 0..5 {
   let character=self.arena.position();if character.x>6.0{self.right=false;}if character.x < -6.0{self.right=true;}if character.z<3.0{self.back=true;}if character.z>9.0{self.back=false;}
   let movement=if self.steps<250{Movement::Idle}else{match self.route{Route::Stationary=>Movement::Idle,Route::Lateral=>if self.right{Movement::Right}else{Movement::Left},Route::Approach=>if self.back{Movement::Backward}else{Movement::Forward},
     Route::House|Route::Pipe=>{
      let points=match self.route{Route::House=>[Vec3::new(0.0,0.0,-3.0),Vec3::new(-5.0,0.0,-3.0),Vec3::new(-5.0,0.0,-1.0),Vec3::new(-1.0,0.0,-3.0),Vec3::new(0.0,0.0,9.0)],_=>[Vec3::new(5.0,0.0,6.0),Vec3::new(5.0,0.0,1.0),Vec3::new(5.0,0.0,-4.0),Vec3::new(0.0,0.0,-4.0),Vec3::new(0.0,0.0,9.0)]};
      let current=self.arena.position();let delta=points[self.stage%5]-Vec3::new(current.x,0.0,current.z);
      if delta.length()<0.2{if self.stage%5==1{self.hold+=1;}else{self.stage+=1;self.hold=0;}Movement::Idle}else{Movement::from([delta.z < -0.12,delta.z>0.12,delta.x < -0.12,delta.x>0.12])}
     }}};self.arena.step(movement);
   let step=self.drone.step(pilot.action(self.observation(),goal).unwrap());self.steps+=1;self.ended=step.is_done();
   let obs=self.observation();let orientation=obs.orientation();let contact=self.sight.sample(&self.arena,obs.position()+orientation*Vec3::new(0.0,0.0,-0.22),Dir3::new(orientation*Vec3::NEG_Z).unwrap(),self.arena.position(),Duration::from_millis(20));
   if let Contact::Visible(point)=contact{
    if let Some(previous)=self.previous_visible{let delta=point-previous;self.velocity=(Vec3::new(delta.x,0.0,delta.z)/0.02).clamp_length_max(4.0);}
    self.previous_visible=Some(point);self.visible+=1;self.first_seen.get_or_insert(self.steps);
    let error=point.distance(obs.position())-5.0;reward+=(1.0/(1.0+error*error/9.0))/5.0;
   }else{self.previous_visible=None;}
   if matches!(contact,Contact::Unknown){self.velocity=Vec3::ZERO;}
   if self.ended{reward-=5.0;break;}
  }
  self.score+=reward;reward
 }
 pub fn trace(&self)->serde_json::Value{serde_json::json!({"time_seconds":self.steps as f32*0.02,"drone_metres":self.observation().position().to_array(),"target_metres":self.arena.position().to_array(),"visible":matches!(self.sight.contact(),Contact::Visible(_)),"stage":self.stage,"hold":self.hold})}
 pub fn result(&self)->serde_json::Value{serde_json::json!({"route":format!("{:?}",self.route),"steps":self.steps,"visible":self.visible,"first_seen":self.first_seen,"ended":self.ended,"score":self.score})}
}

//! Experimental ten-hertz navigation task over the unchanged fifty-hertz flight pilot.
use super::{arena::{Arena,Movement,layout::Surface},sight::{Sight,Contact},flight_control::{FlightGoal,FlightPilot}};
use bevy::math::{Dir2,Dir3,Vec2,Vec3};
use bevy_gym::{Env,robots::{DroneHover,DroneObstacle,DroneObservation}};
use std::time::Duration;

#[derive(Clone,Copy,Debug)]
pub enum Route {Stationary,Lateral,Approach,House,Pipe}
pub struct Task {
